import{_ as e,o as r,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Deploy Ceph in Kubernetes- Rook Deep Dive - Travis Nielsen & Subham Rai, IBM","description":"","frontmatter":{"title":"Deploy Ceph in Kubernetes- Rook Deep Dive - Travis Nielsen & Subham Rai, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Kubernetes","Rook","Distributed Storage","Cloud Native"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Deploy_Ceph_in_Kubernetes_-_Rook_Deep_Dive_-_Travis_Nielsen_Subham_Rai_IBM.md","filePath":"posts/2025/Deploy_Ceph_in_Kubernetes_-_Rook_Deep_Dive_-_Travis_Nielsen_Subham_Rai_IBM.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Deploy_Ceph_in_Kubernetes_-_Rook_Deep_Dive_-_Travis_Nielsen_Subham_Rai_IBM.md"};function n(s,o,l,h,_,p){return r(),a("div",null,[...o[0]||(o[0]=[t('<h3 id="会议纪要-rook-项目深入探讨" tabindex="-1">会议纪要：Rook 项目深入探讨 <a class="header-anchor" href="#会议纪要-rook-项目深入探讨" aria-label="Permalink to &quot;会议纪要：Rook 项目深入探讨&quot;">​</a></h3><p><strong>会议时间</strong>：Cephon 会议最后一天<br><strong>主讲人</strong>：Travis Nielsen (Rook 创始人及维护者) 和 Subham Rai (Rook 维护者)<br><strong>会议主题</strong>：Rook 项目的介绍、架构、功能、社区更新及未来规划</p><h4 id="_1-rook-项目简介" tabindex="-1">1. <strong>Rook 项目简介</strong> <a class="header-anchor" href="#_1-rook-项目简介" aria-label="Permalink to &quot;1. **Rook 项目简介**&quot;">​</a></h4><p>Rook 是一个 Kubernetes 操作符，用于自动化 Ceph 存储的部署、配置、升级和维护。它允许 Kubernetes 应用程序通过标准存储类、持久卷和持久卷声明来访问 Ceph 存储。</p><h4 id="_2-rook-与-ceph-的关系" tabindex="-1">2. <strong>Rook 与 Ceph 的关系</strong> <a class="header-anchor" href="#_2-rook-与-ceph-的关系" aria-label="Permalink to &quot;2. **Rook 与 Ceph 的关系**&quot;">​</a></h4><p>Rook 作为 Ceph 的 Kubernetes 集成层，负责管理 Ceph 集群的部署和维护。Ceph 提供分布式存储的核心功能，包括块存储、文件系统存储和对象存储。</p><h4 id="_3-rook-架构" tabindex="-1">3. <strong>Rook 架构</strong> <a class="header-anchor" href="#_3-rook-架构" aria-label="Permalink to &quot;3. **Rook 架构**&quot;">​</a></h4><p>Rook 采用三层架构：</p><ol><li><strong>Rook 操作符</strong>：负责 Ceph 的部署和管理。</li><li><strong>CSI 驱动程序</strong>：为应用程序提供存储卷的挂载和管理。</li><li><strong>Ceph 数据层</strong>：Ceph 的核心组件（如 OSD、MON、MDS）运行在 Kubernetes Pod 中。</li></ol><h4 id="_4-rook-的功能" tabindex="-1">4. <strong>Rook 的功能</strong> <a class="header-anchor" href="#_4-rook-的功能" aria-label="Permalink to &quot;4. **Rook 的功能**&quot;">​</a></h4><ul><li><strong>存储部署模式</strong>：支持超融合模式、专用存储节点和外部 Ceph 集群。</li><li><strong>CSI 驱动程序功能</strong>：支持拓扑感知、快照、克隆、卷扩展等功能。</li><li><strong>对象存储</strong>：通过 Bucket 声明创建 S3 兼容的存储桶。</li></ul><h4 id="_5-rook-的维护与升级" tabindex="-1">5. <strong>Rook 的维护与升级</strong> <a class="header-anchor" href="#_5-rook-的维护与升级" aria-label="Permalink to &quot;5. **Rook 的维护与升级**&quot;">​</a></h4><ul><li>Rook 支持滚动升级，确保在升级过程中 Ceph 集群的高可用性。</li><li>通过 Pod 干扰预算，Rook 确保在维护或升级时，Ceph 集群不会因节点故障而中断。</li><li>灾难恢复场景中，Rook 确保数据的安全性。</li></ul><h4 id="_6-rook-工具" tabindex="-1">6. <strong>Rook 工具</strong> <a class="header-anchor" href="#_6-rook-工具" aria-label="Permalink to &quot;6. **Rook 工具**&quot;">​</a></h4><ul><li><strong>Rook Toolbox</strong>：提供 Ceph 命令行工具，用于集群故障排查和日常维护。</li><li><strong>Rook Kubernetes 插件</strong>：基于 Kubernetes 的扩展 CLI 工具，简化了集群状态检查和维护操作。</li><li><strong>Mon 仲裁恢复</strong>：支持在 Mon 节点故障时恢复仲裁状态。</li></ul><h4 id="_7-rook-社区与更新" tabindex="-1">7. <strong>Rook 社区与更新</strong> <a class="header-anchor" href="#_7-rook-社区与更新" aria-label="Permalink to &quot;7. **Rook 社区与更新**&quot;">​</a></h4><ul><li>Rook 是一个 CNCF 毕业项目，社区活跃，拥有超过 500 名贡献者和 3.4 亿次下载量。</li><li>每 4 个月发布一次小版本更新，支持最新的 Ceph 版本。</li><li>Rook 1.15 和 1.16 版本新增了多项功能，包括 OSD 加密、Object Store CAS 存储、Ceph CSI 操作符等。</li></ul><h4 id="_8-未来规划" tabindex="-1">8. <strong>未来规划</strong> <a class="header-anchor" href="#_8-未来规划" aria-label="Permalink to &quot;8. **未来规划**&quot;">​</a></h4><ul><li>将 Ceph 打造成 Kubernetes 的最佳存储平台，支持所有 Ceph 和 Kubernetes 的功能。</li><li>重点发展领域：对象存储和数据复制。</li></ul><h4 id="_9-问答环节" tabindex="-1">9. <strong>问答环节</strong> <a class="header-anchor" href="#_9-问答环节" aria-label="Permalink to &quot;9. **问答环节**&quot;">​</a></h4><ul><li>答疑环节涉及了外部 Ceph 集群的使用、性能对比、安全模型等问题。</li></ul><p><strong>总结</strong>：Rook 作为 Ceph 的 Kubernetes 集成层，提供了强大的存储管理能力，支持多种存储类型和部署模式。通过自动化和工具支持，Rook 简化了 Ceph 在 Kubernetes 环境中的使用和维护。未来，Rook 将继续扩展功能，提升与 Ceph 和 Kubernetes 的集成度，目标是成为云原生环境中的最佳存储解决方案。</p>',22)])])}const d=e(i,[["render",n]]);export{u as __pageData,d as default};
